import React, { useState, useCallback, useRef } from "react";
import {
  StyleSheet,
  Text,
  View,
  FlatList,
  Pressable,
  Platform,
  Alert,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { Ionicons } from "@expo/vector-icons";
import { router, useFocusEffect } from "expo-router";
import * as Haptics from "expo-haptics";
import Animated, {
  FadeInDown,
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withSpring,
  runOnJS,
  interpolate,
  Extrapolation,
} from "react-native-reanimated";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Colors from "@/constants/colors";
import {
  GeneratedWorkout,
  TOP_CATEGORY_LABELS,
  getSubTypeLabel,
  TopCategory,
} from "@/lib/exercises";
import { getWorkouts, deleteWorkout, getLocalWorkoutsOnly, getPendingWorkoutCount } from '@/lib/workout-storage';
import AsyncStorage from '@react-native-async-storage/async-storage';

const DELETE_THRESHOLD = -80;
const SNAP_OPEN = -90;

function SwipeableWorkoutItem({ item, index, onDelete }: {
  item: GeneratedWorkout;
  index: number;
  onDelete: (id: string) => void;
}) {
  const translateX = useSharedValue(0);
  const rowHeight = useSharedValue(1);
  const rowOpacity = useSharedValue(1);
  const contextX = useSharedValue(0);
  const isOpen = useRef(false);

  const date = new Date(item.createdAt);
  const dateStr = date.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
  });
  const timeStr = date.toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
  });

  const totalSets = item.exercises.reduce((sum, e) => sum + e.sets, 0);
  const isJustRun = item.subType === "just_run";

  const CATEGORY_COLORS: Record<string, string> = {
    weight_lifting: Colors.primary,
    circuit: Colors.circuit,
    yoga: Colors.yoga,
    cardio: Colors.cardio,
  };
  const catColor = CATEGORY_COLORS[item.topCategory] || Colors.primary;
  const catLabel = TOP_CATEGORY_LABELS[item.topCategory] || "Workout";

  function formatRunTime(secs: number): string {
    const h = Math.floor(secs / 3600);
    const m = Math.floor((secs % 3600) / 60);
    const s = secs % 60;
    if (h > 0) return `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
    return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  }
  const runDist = isJustRun && item.runData
    ? item.runData.unit === "miles"
      ? `${item.runData.distanceMiles.toFixed(2)} mi`
      : `${item.runData.distanceKm.toFixed(2)} km`
    : null;
  const runTime = isJustRun && item.runData ? formatRunTime(item.runData.durationSeconds) : null;

  const triggerDelete = useCallback(() => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    onDelete(item.id);
  }, [item.id, onDelete]);

  const handleDeletePress = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    translateX.value = withTiming(-400, { duration: 250 });
    rowHeight.value = withTiming(0, { duration: 300 });
    rowOpacity.value = withTiming(0, { duration: 250 }, () => {
      runOnJS(triggerDelete)();
    });
  }, [triggerDelete]);

  const panGesture = Gesture.Pan()
    .activeOffsetX([-10, 10])
    .failOffsetY([-5, 5])
    .onStart(() => {
      contextX.value = translateX.value;
    })
    .onUpdate((event) => {
      const newX = contextX.value + event.translationX;
      translateX.value = Math.min(0, Math.max(newX, -150));
    })
    .onEnd((event) => {
      if (translateX.value < DELETE_THRESHOLD) {
        translateX.value = withTiming(SNAP_OPEN, { duration: 200 });
        isOpen.current = true;
        runOnJS(Haptics.impactAsync)(Haptics.ImpactFeedbackStyle.Light);
      } else {
        translateX.value = withTiming(0, { duration: 200 });
        isOpen.current = false;
      }
    });

  const tapGesture = Gesture.Tap()
    .onEnd(() => {
      if (isOpen.current) {
        translateX.value = withTiming(0, { duration: 200 });
        isOpen.current = false;
      } else {
        runOnJS(Haptics.impactAsync)(Haptics.ImpactFeedbackStyle.Light);
        runOnJS(router.push)({ pathname: "/workout/[id]", params: { id: item.id } });
      }
    });

  const composedGesture = Gesture.Race(panGesture, tapGesture);

  const cardAnimStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: translateX.value }],
  }));

  const deleteActionStyle = useAnimatedStyle(() => {
    const actionOpacity = interpolate(
      translateX.value,
      [0, SNAP_OPEN],
      [0, 1],
      Extrapolation.CLAMP,
    );
    return {
      opacity: actionOpacity,
    };
  });

  const rowContainerStyle = useAnimatedStyle(() => ({
    opacity: rowOpacity.value,
    transform: [{ scaleY: rowHeight.value }],
    marginBottom: interpolate(rowHeight.value, [0, 1], [0, 12]),
    overflow: "hidden" as const,
  }));

  return (
    <Animated.View
      entering={FadeInDown.delay(index * 60).duration(350)}
      style={rowContainerStyle}
    >
      <View style={styles.swipeContainer}>
        <Animated.View style={[styles.deleteAction, deleteActionStyle]}>
          <Pressable onPress={handleDeletePress} style={styles.deleteButton}>
            <Ionicons name="trash" size={22} color="#FFF" />
            <Text style={styles.deleteText}>Delete</Text>
          </Pressable>
        </Animated.View>

        <GestureDetector gesture={composedGesture}>
          <Animated.View style={[styles.historyCard, cardAnimStyle]}>
            <View style={styles.historyCardHeader}>
              <View style={styles.historyCardTitleRow}>
                <Text style={styles.historyCardTitle} numberOfLines={1}>
                  {item.name}
                </Text>
                <View style={[styles.styleBadge, { backgroundColor: `${catColor}20` }]}>
                  <Text style={[styles.styleBadgeText, { color: catColor }]}>
                    {catLabel}
                  </Text>
                </View>
              </View>
              <Text style={styles.historyCardType}>
                {getSubTypeLabel(item.topCategory, item.subType)}
              </Text>
            </View>

            <View style={styles.historyCardStats}>
              {isJustRun ? (
                <>
                  <View style={styles.historyStatItem}>
                    <Ionicons name="location-outline" size={14} color={Colors.textMuted} />
                    <Text style={styles.historyStatText}>{runDist ?? "--"}</Text>
                  </View>
                  <View style={styles.historyStatItem}>
                    <Ionicons name="time-outline" size={14} color={Colors.textMuted} />
                    <Text style={styles.historyStatText}>{runTime ?? "--"}</Text>
                  </View>
                  <View style={styles.historyStatItem}>
                    <Ionicons name="footsteps-outline" size={14} color={Colors.textMuted} />
                    <Text style={styles.historyStatText}>GPS Run</Text>
                  </View>
                </>
              ) : (
                <>
                  <View style={styles.historyStatItem}>
                    <Ionicons name="barbell-outline" size={14} color={Colors.textMuted} />
                    <Text style={styles.historyStatText}>
                      {item.exercises.length} exercises
                    </Text>
                  </View>
                  <View style={styles.historyStatItem}>
                    <Ionicons name="layers-outline" size={14} color={Colors.textMuted} />
                    <Text style={styles.historyStatText}>{totalSets} sets</Text>
                  </View>
                  <View style={styles.historyStatItem}>
                    <Ionicons name="time-outline" size={14} color={Colors.textMuted} />
                    <Text style={styles.historyStatText}>{item.durationMinutes} min</Text>
                  </View>
                </>
              )}
            </View>

            {item.topCategory === "circuit" && item.elapsedSeconds != null && (
              <View style={styles.swTimeRow}>
                <Ionicons name="stopwatch-outline" size={12} color={Colors.circuit} />
                <Text style={styles.swTimeText}>{formatRunTime(item.elapsedSeconds)}</Text>
              </View>
            )}

            <View style={styles.historyCardFooter}>
              <Text style={styles.historyDateText}>{dateStr} at {timeStr}</Text>
              <Ionicons name="chevron-forward" size={16} color={Colors.textMuted} />
            </View>
          </Animated.View>
        </GestureDetector>
      </View>
    </Animated.View>
  );
}

const ALL_CATEGORIES: { key: TopCategory; label: string; color: string; icon: string }[] = [
  { key: "weight_lifting", label: "Weights",  color: Colors.primary,  icon: "barbell" },
  { key: "circuit",        label: "Circuit",  color: Colors.circuit,  icon: "flash" },
  { key: "yoga",           label: "Yoga",     color: Colors.yoga,     icon: "leaf" },
  { key: "cardio",         label: "Cardio",   color: Colors.cardio,   icon: "heart" },
  { key: "mobility",       label: "Mobility", color: Colors.mobility, icon: "body" },
];

export default function HistoryScreen() {
  const insets = useSafeAreaInsets();
  const [workouts, setWorkouts] = useState<GeneratedWorkout[]>([]);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [pendingCount, setPendingCount] = useState(0);
  const [legacyPreserved, setLegacyPreserved] = useState(false);
  const [refresh, setRefresh] = useState(0);
  const [filterOpen, setFilterOpen] = useState(false);
  const [pendingFilters, setPendingFilters] = useState<Set<TopCategory>>(new Set());
  const [activeFilters, setActiveFilters] = useState<Set<TopCategory>>(new Set());
  const webTopPad = Platform.OS === "web" ? 67 : 0;

  useFocusEffect(
    useCallback(() => {
      let active = true;
      const load = async () => {
        try {
          const local = await getLocalWorkoutsOnly();
          if (active) { setWorkouts(local); setLoadError(null); }
          const legacy = await AsyncStorage.multiGet(['ironforge_workouts', 'ironforge_profile', 'hidden_exercise_ids', 'pr_reset_timestamps']);
          if (active) setLegacyPreserved(legacy.some(([, value]) => value !== null));
          const data = await getWorkouts();
          const count = await getPendingWorkoutCount();
          if (active) { setWorkouts(data); setPendingCount(count); }
        } catch (error) {
          if (active) setLoadError(error instanceof Error ? error.message : 'Could not load history. Please try again.');
        }
      };
      void load();
      return () => { active = false; };
    // Retry changes callback identity so useFocusEffect reloads while focused.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [refresh]),
  );

  const handleDelete = async (id: string) => {
    try {
      await deleteWorkout(id);
      setWorkouts((prev) => prev.filter((w) => w.id !== id));
      setPendingCount(await getPendingWorkoutCount());
    } catch (error) { Alert.alert('Could not delete workout', error instanceof Error ? error.message : 'Please try again.'); }
  };

  const togglePending = (key: TopCategory) => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    setPendingFilters((prev) => {
      const next = new Set(prev);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    });
  };

  const openFilter = () => {
    setPendingFilters(new Set(activeFilters));
    setFilterOpen(true);
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
  };

  const applyFilter = () => {
    setActiveFilters(new Set(pendingFilters));
    setFilterOpen(false);
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
  };

  const clearFilter = () => {
    setPendingFilters(new Set());
    setActiveFilters(new Set());
    setFilterOpen(false);
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
  };

  const isFiltered = activeFilters.size > 0;
  const displayedWorkouts = isFiltered
    ? workouts.filter((w) => activeFilters.has(w.topCategory as TopCategory))
    : workouts;

  const subtitleText = () => {
    if (workouts.length === 0) return "Your past workouts";
    if (isFiltered) {
      return `${displayedWorkouts.length} of ${workouts.length} workout${workouts.length !== 1 ? "s" : ""}`;
    }
    return `${workouts.length} workout${workouts.length !== 1 ? "s" : ""} generated`;
  };

  const renderEmpty = () => (
    <View style={styles.emptyContainer}>
      <Ionicons name="barbell-outline" size={48} color={Colors.textMuted} />
      <Text style={styles.emptyTitle}>{isFiltered ? "No matching workouts" : "No workouts yet"}</Text>
      <Text style={styles.emptySubtitle}>
        {isFiltered ? "Try adjusting your filters" : "Generate your first workout to see it here"}
      </Text>
    </View>
  );

  return (
    <View style={[styles.container, { paddingTop: insets.top + webTopPad }]}>
      <View style={styles.header}>
        <View style={styles.headerRow}>
          <View>
            <Text style={styles.headerTitle}>History</Text>
            <Text style={styles.headerSubtitle}>{subtitleText()}</Text>
          </View>
          <Pressable
            style={[styles.filterBtn, isFiltered && styles.filterBtnActive]}
            onPress={filterOpen ? () => setFilterOpen(false) : openFilter}
            testID="filter-btn"
          >
            <Ionicons
              name="options-outline"
              size={18}
              color={isFiltered ? Colors.primary : Colors.textSecondary}
            />
            {isFiltered && (
              <View style={styles.filterBadge}>
                <Text style={styles.filterBadgeText}>{activeFilters.size}</Text>
              </View>
            )}
          </Pressable>
        </View>

        {filterOpen && (
          <Animated.View entering={FadeInDown.duration(200)} style={styles.dropdown}>
            {ALL_CATEGORIES.map((cat) => {
              const selected = pendingFilters.has(cat.key);
              return (
                <Pressable
                  key={cat.key}
                  style={[styles.dropdownRow, selected && { backgroundColor: `${cat.color}12` }]}
                  onPress={() => togglePending(cat.key)}
                >
                  <View style={[styles.catDot, { backgroundColor: cat.color }]} />
                  <Ionicons name={cat.icon as any} size={16} color={selected ? cat.color : Colors.textMuted} />
                  <Text style={[styles.dropdownLabel, selected && { color: cat.color, fontFamily: "Rubik_600SemiBold" }]}>
                    {cat.label}
                  </Text>
                  <View style={[styles.checkbox, selected && { backgroundColor: cat.color, borderColor: cat.color }]}>
                    {selected && <Ionicons name="checkmark" size={11} color="#FFF" />}
                  </View>
                </Pressable>
              );
            })}
            <View style={styles.dropdownActions}>
              <Pressable style={styles.clearBtn} onPress={clearFilter}>
                <Text style={styles.clearBtnText}>Clear</Text>
              </Pressable>
              <Pressable style={styles.applyBtn} onPress={applyFilter}>
                <Text style={styles.applyBtnText}>Apply</Text>
              </Pressable>
            </View>
          </Animated.View>
        )}
      </View>

      {legacyPreserved && <Text style={{ color: Colors.textSecondary, paddingHorizontal: 20, paddingBottom: 12 }}>
        Earlier on-device data is preserved separately and is not automatically assigned to this account. Your synced history is shown here.
      </Text>}
      {pendingCount > 0 && <Text accessibilityLiveRegion="polite" style={{ color: Colors.textSecondary, paddingHorizontal: 20, paddingBottom: 12 }}>
        {pendingCount} change{pendingCount === 1 ? '' : 's'} saved on this device, waiting to sync.
      </Text>}
      {loadError && <View style={{ paddingHorizontal: 20, paddingBottom: 12 }}>
        <Text accessibilityLiveRegion="polite" style={{ color: Colors.textSecondary }}>{loadError}</Text>
        <Pressable accessibilityRole="button" onPress={() => setRefresh(value => value + 1)} style={{ paddingVertical: 12 }}>
          <Text style={{ color: Colors.primary }}>Retry</Text>
        </Pressable>
      </View>}
      <FlatList
        data={displayedWorkouts}
        keyExtractor={(item) => item.id}
        renderItem={({ item, index }) => (
          <SwipeableWorkoutItem
            item={item}
            index={index}
            onDelete={handleDelete}
          />
        )}
        contentContainerStyle={[
          styles.listContent,
          { paddingBottom: insets.bottom + 100 },
          displayedWorkouts.length === 0 && styles.emptyList,
        ]}
        ListEmptyComponent={renderEmpty}
        showsVerticalScrollIndicator={false}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: Colors.background,
  },
  header: {
    paddingHorizontal: 20,
    marginTop: 12,
    marginBottom: 16,
  },
  headerTitle: {
    fontSize: 32,
    fontFamily: "Rubik_700Bold",
    color: Colors.text,
    letterSpacing: -0.5,
  },
  headerSubtitle: {
    fontSize: 14,
    fontFamily: "Rubik_400Regular",
    color: Colors.textSecondary,
    marginTop: 2,
  },
  listContent: {
    paddingHorizontal: 20,
  },
  emptyList: {
    flex: 1,
    justifyContent: "center",
  },
  emptyContainer: {
    alignItems: "center",
    gap: 10,
    paddingBottom: 80,
  },
  emptyTitle: {
    fontSize: 18,
    fontFamily: "Rubik_600SemiBold",
    color: Colors.textSecondary,
  },
  emptySubtitle: {
    fontSize: 14,
    fontFamily: "Rubik_400Regular",
    color: Colors.textMuted,
    textAlign: "center",
  },
  swipeContainer: {
    position: "relative",
    borderRadius: 16,
    overflow: "hidden",
  },
  deleteAction: {
    position: "absolute",
    right: 0,
    top: 0,
    bottom: 0,
    width: 90,
    backgroundColor: Colors.error,
    borderTopRightRadius: 16,
    borderBottomRightRadius: 16,
    justifyContent: "center",
    alignItems: "center",
  },
  deleteButton: {
    alignItems: "center",
    justifyContent: "center",
    gap: 4,
    width: "100%",
    height: "100%",
  },
  deleteText: {
    fontSize: 11,
    fontFamily: "Rubik_600SemiBold",
    color: "#FFF",
  },
  historyCard: {
    backgroundColor: Colors.surface,
    borderRadius: 16,
    padding: 16,
    borderWidth: 1,
    borderColor: Colors.border,
  },
  historyCardHeader: {
    marginBottom: 12,
  },
  historyCardTitleRow: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    gap: 8,
  },
  historyCardTitle: {
    fontSize: 17,
    fontFamily: "Rubik_600SemiBold",
    color: Colors.text,
    flex: 1,
  },
  styleBadge: {
    paddingHorizontal: 8,
    paddingVertical: 3,
    borderRadius: 6,
  },
  styleBadgeText: {
    fontSize: 11,
    fontFamily: "Rubik_700Bold",
    letterSpacing: 0.5,
  },
  historyCardType: {
    fontSize: 13,
    fontFamily: "Rubik_400Regular",
    color: Colors.textSecondary,
    marginTop: 3,
  },
  historyCardStats: {
    flexDirection: "row",
    gap: 16,
    marginBottom: 12,
  },
  historyStatItem: {
    flexDirection: "row",
    alignItems: "center",
    gap: 4,
  },
  historyStatText: {
    fontSize: 12,
    fontFamily: "Rubik_500Medium",
    color: Colors.textMuted,
  },
  historyCardFooter: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    borderTopWidth: 1,
    borderTopColor: Colors.border,
    paddingTop: 10,
  },
  historyDateText: {
    fontSize: 12,
    fontFamily: "Rubik_400Regular",
    color: Colors.textMuted,
  },
  swTimeRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 5,
    paddingVertical: 6,
    paddingHorizontal: 8,
    borderRadius: 8,
    backgroundColor: `${Colors.circuit}15`,
    alignSelf: "flex-start",
    marginBottom: 8,
  },
  swTimeText: {
    fontSize: 12,
    fontFamily: "Rubik_600SemiBold",
    color: Colors.circuit,
  },
  headerRow: {
    flexDirection: "row",
    alignItems: "flex-start",
    justifyContent: "space-between",
  },
  filterBtn: {
    flexDirection: "row",
    alignItems: "center",
    backgroundColor: Colors.surface,
    borderWidth: 1,
    borderColor: Colors.border,
    borderRadius: 10,
    paddingHorizontal: 12,
    paddingVertical: 8,
    marginTop: 4,
    gap: 6,
  },
  filterBtnActive: {
    borderColor: Colors.primary,
    backgroundColor: `${Colors.primary}10`,
  },
  filterBadge: {
    backgroundColor: Colors.primary,
    borderRadius: 8,
    minWidth: 16,
    height: 16,
    alignItems: "center",
    justifyContent: "center",
    paddingHorizontal: 3,
  },
  filterBadgeText: {
    fontSize: 10,
    fontFamily: "Rubik_700Bold",
    color: "#FFF",
  },
  dropdown: {
    backgroundColor: Colors.surface,
    borderRadius: 14,
    borderWidth: 1,
    borderColor: Colors.border,
    marginTop: 12,
    overflow: "hidden",
  },
  dropdownRow: {
    flexDirection: "row",
    alignItems: "center",
    paddingHorizontal: 16,
    paddingVertical: 13,
    gap: 10,
    borderBottomWidth: 1,
    borderBottomColor: Colors.border,
  },
  catDot: {
    width: 7,
    height: 7,
    borderRadius: 4,
  },
  dropdownLabel: {
    flex: 1,
    fontSize: 15,
    fontFamily: "Rubik_400Regular",
    color: Colors.text,
  },
  checkbox: {
    width: 20,
    height: 20,
    borderRadius: 5,
    borderWidth: 1.5,
    borderColor: Colors.border,
    alignItems: "center",
    justifyContent: "center",
  },
  dropdownActions: {
    flexDirection: "row",
    gap: 10,
    padding: 14,
  },
  clearBtn: {
    flex: 1,
    paddingVertical: 11,
    borderRadius: 10,
    backgroundColor: Colors.surfaceLight,
    alignItems: "center",
    borderWidth: 1,
    borderColor: Colors.border,
  },
  clearBtnText: {
    fontFamily: "Rubik_500Medium",
    fontSize: 14,
    color: Colors.textSecondary,
  },
  applyBtn: {
    flex: 2,
    paddingVertical: 11,
    borderRadius: 10,
    backgroundColor: Colors.primary,
    alignItems: "center",
  },
  applyBtnText: {
    fontFamily: "Rubik_600SemiBold",
    fontSize: 14,
    color: "#FFF",
  },
});

import React, { useState, useCallback } from "react";
import {
  StyleSheet,
  Text,
  View,
  ScrollView,
  Pressable,
  Platform,
  Image,
  Alert,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { Ionicons, MaterialCommunityIcons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { router } from "expo-router";
import * as Haptics from "expo-haptics";
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withSequence,
  FadeIn,
} from "react-native-reanimated";
import Colors from "@/constants/colors";
import {
  TopCategory,
  WeightLiftingType,
  CircuitStyle,
  YogaStyle,
  CardioStyle,
  MobilityStyle,
  TrainingStyle,
  WEIGHT_LIFTING_LABELS,
  CIRCUIT_STYLE_LABELS,
  YOGA_STYLE_LABELS,
  CARDIO_STYLE_LABELS,
  MOBILITY_STYLE_LABELS,
  DURATION_OPTIONS,
  MOBILITY_DURATION_OPTIONS,
  generateWorkout,
  getSubTypeLabel,
} from "@/lib/exercises";
import { saveWorkout } from "@/lib/workout-storage";
import { getAccountScope, assertAccountScope } from '@/lib/account-scope';
import { useCustomExercises } from "@/lib/useCustomExercises";
import { useHiddenExercises } from "@/lib/useHiddenExercises";

const CATEGORIES: { key: TopCategory; label: string; icon: string; iconSet: "ionicons" | "mci"; color: string; desc: string }[] = [
  { key: "weight_lifting", label: "Weights", icon: "barbell", iconSet: "ionicons", color: Colors.primary, desc: "Traditional splits" },
  { key: "circuit", label: "Circuit", icon: "flash", iconSet: "ionicons", color: Colors.circuit, desc: "CrossFit / Hyrox" },
  { key: "yoga", label: "Yoga", icon: "meditation", iconSet: "mci", color: Colors.yoga, desc: "Core & Flexibility" },
  { key: "cardio", label: "Cardio", icon: "heart", iconSet: "ionicons", color: Colors.cardio, desc: "Run & Mixed" },
  { key: "mobility", label: "Mobility", icon: "body", iconSet: "ionicons", color: Colors.mobility, desc: "Move & Restore" },
];

const MOBILITY_TYPES: { key: MobilityStyle; icon: string; iconSet: "ionicons" | "mci" }[] = [
  { key: "full_body", icon: "body", iconSet: "ionicons" },
  { key: "lower_body", icon: "walk", iconSet: "ionicons" },
  { key: "upper_body", icon: "hand-left", iconSet: "ionicons" },
  { key: "hips_and_spine", icon: "git-compare", iconSet: "ionicons" },
];

const WEIGHT_TYPES: { key: WeightLiftingType; icon: string; iconSet: "ionicons" | "mci" }[] = [
  { key: "chest_triceps", icon: "body", iconSet: "ionicons" },
  { key: "back_biceps", icon: "arm-flex", iconSet: "mci" },
  { key: "shoulders_abs", icon: "human-handsup", iconSet: "mci" },
  { key: "legs", icon: "walk", iconSet: "ionicons" },
  { key: "push", icon: "arrow-up-circle", iconSet: "ionicons" },
  { key: "pull", icon: "arrow-down-circle", iconSet: "ionicons" },
  { key: "full_body", icon: "fitness", iconSet: "ionicons" },
];

function CategoryCard({ item, selected, onPress }: {
  item: typeof CATEGORIES[0];
  selected: boolean;
  onPress: () => void;
}) {
  const scale = useSharedValue(1);
  const animStyle = useAnimatedStyle(() => ({ transform: [{ scale: scale.value }] }));

  const handlePress = () => {
    scale.value = withSequence(withSpring(0.93, { damping: 15 }), withSpring(1, { damping: 12 }));
    onPress();
  };

  return (
    <Pressable onPress={handlePress} style={{ flex: 1 }}>
      <Animated.View style={[styles.categoryCard, selected && { borderColor: item.color, backgroundColor: `${item.color}10` }, animStyle]}>
        {item.iconSet === "ionicons" ? (
          <Ionicons name={item.icon as any} size={26} color={selected ? item.color : Colors.textSecondary} />
        ) : (
          <MaterialCommunityIcons name={item.icon as any} size={26} color={selected ? item.color : Colors.textSecondary} />
        )}
        <Text style={[styles.categoryLabel, selected && { color: item.color }]}>{item.label}</Text>
        <Text style={[styles.categoryDesc, selected && { color: `${item.color}AA` }]} numberOfLines={1}>{item.desc}</Text>
      </Animated.View>
    </Pressable>
  );
}

function OptionPill({ label, selected, color, onPress }: {
  label: string; selected: boolean; color: string; onPress: () => void;
}) {
  return (
    <Pressable
      onPress={() => { Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light); onPress(); }}
      style={[styles.optionPill, selected && { borderColor: color, backgroundColor: `${color}15` }]}
    >
      <Text style={[styles.optionPillText, selected && { color }]}>{label}</Text>
    </Pressable>
  );
}

function SubTypeSelector({ category, subType, onSelect, color }: {
  category: TopCategory;
  subType: string;
  onSelect: (s: string) => void;
  color: string;
}) {
  let options: { key: string; label: string; icon?: string; iconSet?: "ionicons" | "mci" }[] = [];

  switch (category) {
    case "weight_lifting":
      return (
        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.typeRow}>
          {WEIGHT_TYPES.map((item) => {
            const selected = subType === item.key;
            return (
              <Pressable
                key={item.key}
                onPress={() => { Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light); onSelect(item.key); }}
              >
                <View style={[styles.typeCard, selected && { borderColor: color, backgroundColor: `${color}10` }]}>
                  {item.iconSet === "ionicons" ? (
                    <Ionicons name={item.icon as any} size={20} color={selected ? color : Colors.textSecondary} />
                  ) : (
                    <MaterialCommunityIcons name={item.icon as any} size={20} color={selected ? color : Colors.textSecondary} />
                  )}
                  <Text style={[styles.typeCardText, selected && { color }]} numberOfLines={2}>
                    {WEIGHT_LIFTING_LABELS[item.key]}
                  </Text>
                </View>
              </Pressable>
            );
          })}
        </ScrollView>
      );
    case "circuit":
      options = Object.entries(CIRCUIT_STYLE_LABELS).map(([k, v]) => ({ key: k, label: v }));
      break;
    case "yoga":
      options = Object.entries(YOGA_STYLE_LABELS).map(([k, v]) => ({ key: k, label: v }));
      break;
    case "cardio":
      options = Object.entries(CARDIO_STYLE_LABELS).map(([k, v]) => ({ key: k, label: v }));
      break;
    case "mobility":
      return (
        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.typeRow}>
          {MOBILITY_TYPES.map((item) => {
            const selected = subType === item.key;
            return (
              <Pressable
                key={item.key}
                onPress={() => { Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light); onSelect(item.key); }}
              >
                <View style={[styles.typeCard, selected && { borderColor: color, backgroundColor: `${color}10` }]}>
                  {item.iconSet === "ionicons" ? (
                    <Ionicons name={item.icon as any} size={20} color={selected ? color : Colors.textSecondary} />
                  ) : (
                    <MaterialCommunityIcons name={item.icon as any} size={20} color={selected ? color : Colors.textSecondary} />
                  )}
                  <Text style={[styles.typeCardText, selected && { color }]} numberOfLines={2}>
                    {MOBILITY_STYLE_LABELS[item.key]}
                  </Text>
                </View>
              </Pressable>
            );
          })}
        </ScrollView>
      );
  }

  return (
    <View style={styles.pillRow}>
      {options.map((opt) => (
        <OptionPill
          key={opt.key}
          label={opt.label}
          selected={subType === opt.key}
          color={color}
          onPress={() => onSelect(opt.key)}
        />
      ))}
    </View>
  );
}

function StyleToggle({ style, onToggle }: {
  style: TrainingStyle;
  onToggle: (s: TrainingStyle) => void;
}) {
  const isStrength = style === "strength";
  return (
    <View style={styles.styleToggleContainer}>
      <Pressable
        style={[styles.styleToggleBtn, isStrength && styles.styleToggleBtnActive]}
        onPress={() => { Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light); onToggle("strength"); }}
      >
        <Ionicons name="barbell" size={18} color={isStrength ? "#FFF" : Colors.textSecondary} />
        <Text style={[styles.styleToggleText, isStrength && styles.styleToggleTextActive]}>Strength</Text>
        <Text style={[styles.styleToggleSubtext, isStrength && { color: "rgba(255,255,255,0.7)" }]}>4-6 reps</Text>
      </Pressable>
      <Pressable
        style={[styles.styleToggleBtn, !isStrength && styles.styleToggleBtnHyper]}
        onPress={() => { Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light); onToggle("hypertrophy"); }}
      >
        <Ionicons name="pulse" size={18} color={!isStrength ? "#FFF" : Colors.textSecondary} />
        <Text style={[styles.styleToggleText, !isStrength && styles.styleToggleTextActive]}>Hypertrophy</Text>
        <Text style={[styles.styleToggleSubtext, !isStrength && { color: "rgba(255,255,255,0.7)" }]}>8-12 reps</Text>
      </Pressable>
    </View>
  );
}

function DurationPicker({ duration, onSelect, color, options }: {
  duration: number; onSelect: (d: number) => void; color: string; options?: number[];
}) {
  const durations = options || DURATION_OPTIONS;
  return (
    <View style={styles.durationRow}>
      {durations.map((d) => {
        const selected = d === duration;
        return (
          <Pressable
            key={d}
            style={[styles.durationChip, selected && { borderColor: color, backgroundColor: `${color}15` }]}
            onPress={() => { Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light); onSelect(d); }}
          >
            <Text style={[styles.durationChipText, selected && { color }]}>{d}</Text>
            <Text style={[styles.durationChipLabel, selected && { color: `${color}AA` }]}>min</Text>
          </Pressable>
        );
      })}
    </View>
  );
}

const DEFAULT_SUB_TYPES: Record<TopCategory, string> = {
  weight_lifting: "chest_triceps",
  circuit: "amrap",
  yoga: "core_strength",
  cardio: "running",
  mobility: "full_body",
};

export default function GenerateScreen() {
  const insets = useSafeAreaInsets();
  const { customExercises } = useCustomExercises();
  const { hiddenIds } = useHiddenExercises();
  const [selectedCategory, setSelectedCategory] = useState<TopCategory>("weight_lifting");
  const [subTypes, setSubTypes] = useState<Record<TopCategory, string>>(DEFAULT_SUB_TYPES);
  const [trainingStyle, setTrainingStyle] = useState<TrainingStyle>("hypertrophy");
  const [selectedDuration, setSelectedDuration] = useState(45);
  const [includeSupersets, setIncludeSupersets] = useState(false);
  const [includeCore, setIncludeCore] = useState(false);
  const [generating, setGenerating] = useState(false);
  const buttonScale = useSharedValue(1);
  const buttonAnimStyle = useAnimatedStyle(() => ({ transform: [{ scale: buttonScale.value }] }));

  const currentSubType = subTypes[selectedCategory];
  const catColor = CATEGORIES.find(c => c.key === selectedCategory)?.color || Colors.primary;

  const handleSubTypeChange = (val: string) => {
    setSubTypes(prev => ({ ...prev, [selectedCategory]: val }));
  };

  const isJustRun = selectedCategory === "cardio" && currentSubType === "just_run";

  const handleGenerate = useCallback(async () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy);
    buttonScale.value = withSequence(withSpring(0.95, { damping: 15 }), withSpring(1, { damping: 10 }));

    if (isJustRun) {
      router.push("/run/setup");
      return;
    }

    setGenerating(true);
    const scope = getAccountScope();
    await new Promise(r => setTimeout(r, 400));

    try {
      assertAccountScope(scope);
      const style = selectedCategory === "weight_lifting" ? trainingStyle : currentSubType;
      const workout = generateWorkout(selectedCategory, currentSubType, style, selectedDuration, includeSupersets, includeCore, customExercises, hiddenIds);
      workout.userId = scope.userId;
      await saveWorkout(workout);
      assertAccountScope(scope);
      router.push({ pathname: "/workout/[id]", params: { id: workout.id, fresh: "true" } });
    } catch (error) {
      Alert.alert("Could not create workout", error instanceof Error ? error.message : "Please try again.");
    } finally {
      setGenerating(false);
    }
  }, [selectedCategory, currentSubType, trainingStyle, selectedDuration, includeSupersets, includeCore, customExercises, hiddenIds, isJustRun]);

  const webTopPad = Platform.OS === "web" ? 67 : 0;

  const getSummaryLabel = (): string => {
    return getSubTypeLabel(selectedCategory, currentSubType);
  };

  return (
    <View style={[styles.container, { paddingTop: insets.top + webTopPad }]}>
      <ScrollView
        contentContainerStyle={[styles.scrollContent, { paddingBottom: insets.bottom + 100 }]}
        showsVerticalScrollIndicator={false}
      >
        <View style={styles.header}>
          <View>
            <Text style={styles.headerTitle}>Swole House</Text>
            <Text style={styles.headerSubtitle}>Build your workout</Text>
          </View>
          <Image
            source={require("@/assets/images/logo-transparent.png")}
            style={styles.headerLogo}
            resizeMode="contain"
          />
        </View>

        <Animated.View entering={FadeIn.delay(100).duration(400)}>
          <Text style={styles.sectionTitle}>Category</Text>
          <View style={styles.categoryRow}>
            {CATEGORIES.map((cat) => (
              <CategoryCard
                key={cat.key}
                item={cat}
                selected={selectedCategory === cat.key}
                onPress={() => {
                  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
                  setSelectedCategory(cat.key);
                  if (cat.key === "mobility") {
                    if (!MOBILITY_DURATION_OPTIONS.includes(selectedDuration)) {
                      setSelectedDuration(20);
                    }
                  } else {
                    if (!DURATION_OPTIONS.includes(selectedDuration)) {
                      setSelectedDuration(45);
                    }
                  }
                }}
              />
            ))}
          </View>
        </Animated.View>

        <Animated.View entering={FadeIn.delay(200).duration(400)}>
          <Text style={styles.sectionTitle}>
            {selectedCategory === "weight_lifting" ? "Muscle Group" :
             selectedCategory === "circuit" ? "Format" :
             selectedCategory === "yoga" ? "Focus" :
             selectedCategory === "mobility" ? "Focus Area" : "Type"}
          </Text>
          <SubTypeSelector
            category={selectedCategory}
            subType={currentSubType}
            onSelect={handleSubTypeChange}
            color={catColor}
          />
        </Animated.View>

        {selectedCategory === "weight_lifting" && (
          <Animated.View entering={FadeIn.delay(250).duration(400)}>
            <Text style={styles.sectionTitle}>Training Style</Text>
            <StyleToggle style={trainingStyle} onToggle={setTrainingStyle} />

            <View style={styles.toggleRow}>
              <Pressable
                onPress={() => {
                  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                  setIncludeSupersets(prev => !prev);
                }}
                style={[styles.supersetToggle, includeSupersets && styles.supersetToggleActive]}
              >
                <View style={styles.supersetToggleTop}>
                  <View style={[styles.supersetIconWrap, includeSupersets && styles.supersetIconWrapActive]}>
                    <Ionicons name="git-compare" size={18} color={includeSupersets ? "#FFF" : Colors.textSecondary} />
                  </View>
                  <View style={[styles.supersetSwitch, includeSupersets && styles.supersetSwitchActive]}>
                    <Animated.View style={[styles.supersetSwitchThumb, includeSupersets && styles.supersetSwitchThumbActive]} />
                  </View>
                </View>
                <Text style={[styles.supersetToggleTitle, includeSupersets && { color: Colors.primary }]}>Supersets</Text>
                <Text style={styles.supersetToggleDesc}>
                  {selectedDuration >= 60 ? "2 pairs" : "1 pair"}
                </Text>
              </Pressable>

              <Pressable
                onPress={() => {
                  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                  setIncludeCore(prev => !prev);
                }}
                style={[styles.supersetToggle, includeCore && styles.supersetToggleActive]}
              >
                <View style={styles.supersetToggleTop}>
                  <View style={[styles.supersetIconWrap, includeCore && styles.supersetIconWrapActive]}>
                    <Ionicons name="fitness" size={18} color={includeCore ? "#FFF" : Colors.textSecondary} />
                  </View>
                  <View style={[styles.supersetSwitch, includeCore && styles.supersetSwitchActive]}>
                    <Animated.View style={[styles.supersetSwitchThumb, includeCore && styles.supersetSwitchThumbActive]} />
                  </View>
                </View>
                <Text style={[styles.supersetToggleTitle, includeCore && { color: Colors.primary }]}>Core</Text>
                <Text style={styles.supersetToggleDesc}>Add ab finisher</Text>
              </Pressable>
            </View>
          </Animated.View>
        )}

        {!isJustRun && (
          <Animated.View entering={FadeIn.delay(300).duration(400)}>
            <Text style={styles.sectionTitle}>Duration</Text>
            <DurationPicker
              duration={selectedDuration}
              onSelect={setSelectedDuration}
              color={catColor}
              options={selectedCategory === "mobility" ? MOBILITY_DURATION_OPTIONS : DURATION_OPTIONS}
            />
          </Animated.View>
        )}

        <Animated.View
          entering={FadeIn.delay(350).duration(400)}
          style={styles.summaryCard}
        >
          <LinearGradient
            colors={[Colors.surfaceLight, Colors.surface]}
            style={styles.summaryGradient}
          >
            <View style={styles.summaryRow}>
              <View style={styles.summaryItem}>
                <View style={[styles.summaryDot, { backgroundColor: catColor }]} />
                <Text style={styles.summaryLabel}>
                  {CATEGORIES.find(c => c.key === selectedCategory)?.label}
                </Text>
              </View>
              <View style={styles.summaryDivider} />
              <View style={styles.summaryItem}>
                <Ionicons name="options" size={14} color={catColor} />
                <Text style={styles.summaryLabel}>{getSummaryLabel()}</Text>
              </View>
              {!isJustRun && (
                <>
                  <View style={styles.summaryDivider} />
                  <View style={styles.summaryItem}>
                    <Ionicons name="time" size={14} color={Colors.accent} />
                    <Text style={styles.summaryLabel}>{selectedDuration} min</Text>
                  </View>
                </>
              )}
              {isJustRun && (
                <>
                  <View style={styles.summaryDivider} />
                  <View style={styles.summaryItem}>
                    <Ionicons name="location" size={14} color={catColor} />
                    <Text style={styles.summaryLabel}>GPS Tracked</Text>
                  </View>
                </>
              )}
            </View>
          </LinearGradient>
        </Animated.View>

        <Animated.View style={buttonAnimStyle}>
          <Pressable
            style={[styles.generateButton, generating && styles.generateButtonDisabled]}
            onPress={handleGenerate}
            disabled={generating}
          >
            <LinearGradient
              colors={[catColor, `${catColor}CC`]}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={styles.generateGradient}
            >
              {generating ? (
                <Text style={styles.generateText}>Forging...</Text>
              ) : isJustRun ? (
                <>
                  <Ionicons name="location" size={22} color="#FFF" />
                  <Text style={styles.generateText}>Set Up Run</Text>
                </>
              ) : (
                <>
                  <Ionicons name="flash" size={22} color="#FFF" />
                  <Text style={styles.generateText}>Generate Workout</Text>
                </>
              )}
            </LinearGradient>
          </Pressable>
        </Animated.View>
      </ScrollView>
    </View>
  );
}

