function toExercise(c: CustomExerciseData): Exercise {
  return { id: c.id, name: c.name, muscles: c.muscles, category: c.type, equipment: c.equipment };
}

function getCustomForCategory(topCategory: TopCategory, subType: string, customExercises?: CustomExerciseData[]): Exercise[] {
  if (!customExercises?.length) return [];
  return customExercises
    .filter(c => c.topCategories.includes(topCategory))
    .filter(c => {
      if (topCategory !== 'weight_lifting') return true;
      return c.weightSubCategories.length === 0 || c.weightSubCategories.includes(subType as WeightLiftingType);
    })
    .map(toExercise);
}

function getExercisePool(topCategory: TopCategory, subType: string, customExercises?: CustomExerciseData[], hiddenIds?: string[]): Exercise[] {
  const custom = getCustomForCategory(topCategory, subType, customExercises);
  let pool: Exercise[];
  switch (topCategory) {
    case 'weight_lifting': {
      const muscles = WORKOUT_TYPE_MUSCLES[subType as WeightLiftingType];
      const base = muscles
        ? WEIGHT_EXERCISES.filter(e => e.muscles.some(m => muscles.includes(m)))
        : WEIGHT_EXERCISES;
      const filteredCustom = muscles
        ? custom.filter(e => e.muscles.some(m => muscles.includes(m)))
        : custom;
      pool = [...base, ...filteredCustom];
      break;
    }
    case 'circuit':
      pool = [...CIRCUIT_EXERCISES, ...custom]; break;
    case 'yoga':
      pool = [...(subType === 'flexibility' ? YOGA_FLEX_POSES : YOGA_CORE_POSES), ...custom]; break;
    case 'cardio':
      pool = [...(subType === 'running' ? CARDIO_RUNNING : CARDIO_MIXED), ...custom]; break;
    case 'mobility':
      pool = [...getMobilityPool(subType as MobilityStyle), ...custom]; break;
    default:
      return [];
  }
  if (hiddenIds?.length) pool = pool.filter(e => !hiddenIds.includes(e.id));
  return pool;
}

export function pickRandomNewExercise(
  topCategory: TopCategory,
  subType: string,
  usedIds: string[],
  customExercises?: CustomExerciseData[],
  hiddenIds?: string[]
): Exercise | null {
  const pool = getExercisePool(topCategory, subType, customExercises, hiddenIds);
  const candidates = pool.filter(e => !usedIds.includes(e.id));
  if (candidates.length === 0) return null;
  return candidates[Math.floor(Math.random() * candidates.length)];
}

export function findReplacementExercise(
  current: Exercise,
  topCategory: TopCategory,
  subType: string,
  usedIds: string[],
  customExercises?: CustomExerciseData[],
  hiddenIds?: string[]
): Exercise | null {
  const pool = getExercisePool(topCategory, subType, customExercises, hiddenIds);

  const candidates = pool.filter(e =>
    e.id !== current.id &&
    !usedIds.includes(e.id) &&
    e.muscles.some(m => current.muscles.includes(m))
  );

  if (candidates.length > 0) {
    return candidates[Math.floor(Math.random() * candidates.length)];
  }

  const fallbackCandidates = pool.filter(e =>
    e.id !== current.id &&
    !usedIds.includes(e.id)
  );

  if (fallbackCandidates.length > 0) {
    return fallbackCandidates[Math.floor(Math.random() * fallbackCandidates.length)];
  }

  return null;
}

export function findCoreReplacementExercise(
  current: Exercise,
  usedIds: string[],
  customExercises?: CustomExerciseData[],
  hiddenIds?: string[]
): Exercise | null {
  const customWeight = getCustomForCategory('weight_lifting', 'shoulders_abs', customExercises);
  let pool = [...WEIGHT_EXERCISES, ...customWeight];
  if (hiddenIds?.length) pool = pool.filter(e => !hiddenIds.includes(e.id));
  const candidates = pool.filter(e =>
    e.id !== current.id &&
    !usedIds.includes(e.id) &&
    e.muscles.includes('abs')
  );
  if (candidates.length > 0) {
    return candidates[Math.floor(Math.random() * candidates.length)];
  }
  return null;
}

