  lower_body:   ['mob1', 'mob2', 'mob3', 'mob4', 'mob15', 'mob20', 'mob23', 'mob24', 'mob5', 'mob19'],
  upper_body:   ['mob6', 'mob7', 'mob9', 'mob18', 'mob21', 'mob12', 'mob8', 'mob10'],
  hips_and_spine: ['mob5', 'mob13', 'mob14', 'mob18', 'mob19', 'mob22', 'mob24', 'mob3', 'mob9', 'mob20'],
